11	// 全程整数运算，不经过浮点数。
12	
13	var errOverflow = errors.New("数量或金额运算超出有符号 64 位整数范围")
14	
15	// mul64 返回 a*b，溢出时返回错误。a、b 均非负。
16	func mul64(a, b int64) (int64, error) {
17		if a < 0 || b < 0 {
18			return 0, errOverflow
19		}
20		if a == 0 || b == 0 {
21			return 0, nil
22		}
23		if a > math.MaxInt64/b {
24			return 0, errOverflow
25		}
26		return a * b, nil
27	}
