78	func moneyFen(fen int64) string {
79		neg := fen < 0
80		// 用无符号数取绝对值，避免 math.MinInt64 取负溢出。
81		u := uint64(fen)
82		if neg {
83			u = uint64(-(fen + 1)) + 1
84		}
