86		if len(s) < 3 {
87			s = "00" + s
88			s = s[len(s)-3:]
89		}
90		whole, frac := s[:len(s)-2], s[len(s)-2:]
91		out := whole + "." + frac + " 元"
92		if neg {
93			out = "-" + out
94		}
95		return out
96	}
