776	// validatePlanRules 校验阶梯方案的标识、名称、月费与阶梯规则本身自洽：
777	// 月费为非负整数分，至少一档，有限上限为严格递增的正整数，最后一档无
778	// 上限，单价非负。
779	func validatePlanRules(p *plan) error {
780		if p.ID == "" || p.Name == "" {
781			return fmt.Errorf("方案 %q 的标识或名称为空", p.ID)
782		}
783		if p.MonthlyFee < 0 {
784			return fmt.Errorf("方案 %q 的月费为负", p.ID)
785		}
786		if len(p.Tiers) == 0 {
787			return fmt.Errorf("方案 %q 至少需要一档阶梯", p.ID)
788		}
789		prev := int64(0)
790		for i, t := range p.Tiers {
791			if t.Price < 0 {
792				return fmt.Errorf("方案 %q 第 %d 档单价为负", p.ID, i+1)
793			}
794			if i == len(p.Tiers)-1 {
795				if t.Limit != 0 {
796					return fmt.Errorf("方案 %q 最后一档必须无上限", p.ID)
797				}
798			} else {
799				if t.Limit <= 0 {
800					return fmt.Errorf("方案 %q 第 %d 档上限必须是正整数", p.ID, i+1)
801				}
802				if t.Limit <= prev {
803					return fmt.Errorf("方案 %q 的有限上限必须严格递增", p.ID)
804				}
805				prev = t.Limit
806			}
807		}
808		return nil
809	}
