837	// sortedByInstant 判定用量记录是否按（解析后的时间点升序、同一时间按
838	// 标识字典序）排列，即阶梯计价的计价顺序。
839	func sortedByInstant(recs []*usageRecord) bool {
840		for i := 1; i < len(recs); i++ {
841			ti, _ := time.Parse(time.RFC3339, recs[i-1].Time)
842			tj, _ := time.Parse(time.RFC3339, recs[i].Time)
843			ui, uj := ti.UTC(), tj.UTC()
844			if uj.Before(ui) || (uj.Equal(ui) && recs[i].ID <= recs[i-1].ID) {
845				return false
846			}
847		}
848		return true
849	}
