851	// validateTieredBill 校验阶梯账单：方案引用有效、快照与方案一致、账单方案
852	// 符合账期月的方案安排，并按保存的方案规则从零累计重放计价，逐条比对分段、
853	// 小计、各档合计与总金额；任何不符都视为数据损坏。
854	func (s *state) validateTieredBill(key string, b *bill, c *customer) error {
855		if b.PlanID == "" {
856			return fmt.Errorf("账单 %q 缺少方案标识", key)
857		}
858		p, ok := s.Plans[b.PlanID]
859		if !ok {
860			return fmt.Errorf("账单 %q 引用了不存在的方案 %q", key, b.PlanID)
861		}
862		if b.PlanName != p.Name {
863			return fmt.Errorf("账单 %q 的方案名称快照与方案 %q 不符", key, b.PlanID)
864		}
865		if !tiersEqual(b.PlanTiers, p.Tiers) {
866			return fmt.Errorf("账单 %q 的方案规则快照与方案 %q 不符", key, b.PlanID)
867		}
868		if b.MonthlyFee != p.MonthlyFee {
869			return fmt.Errorf("账单 %q 的月费快照与方案 %q 不符", key, b.PlanID)
870		}
871		// 账单方案必须符合账期安排：创建时绑定的初始方案被生效月不晚于
872		// 账期月的最后一次变更替换（无变更时即初始绑定，兼容旧存档）。
873		if want := s.effectivePlanID(c, b.Month); want != b.PlanID {
874			return fmt.Errorf("账单 %q 的方案 %q 与账期 %s 安排的方案 %q 不一致", key, b.PlanID, b.Month, want)
875		}
876		if b.UnitPrice != 0 {
877			return fmt.Errorf("账单 %q 是阶梯账单但保存了统一单价", key)
878		}
879		if len(b.TierTotals) != len(p.Tiers) {
880			return fmt.Errorf("账单 %q 的分档合计档数与方案规则不符", key)
881		}
882		// 明细必须按计价顺序排列（前面已逐条核验与用量记录一致）。
883		recs := make([]*usageRecord, len(b.Lines))
884		for i, ln := range b.Lines {
885			recs[i] = s.Usage[ln.UsageID]
886		}
887		if !sortedByInstant(recs) {
888			return fmt.Errorf("账单 %q 的明细未按计价顺序（时间点升序、同一时间按标识字典序）排列", key)
889		}
890		priced, err := tieredPrice(p.Tiers, recs)
891		if err != nil {
892			return fmt.Errorf("账单 %q 按方案规则计价失败: %w", key, err)
893		}
894		for i, ln := range b.Lines {
895			if !segmentsEqual(ln.Segments, priced.lines[i].segments) {
896				return fmt.Errorf("账单 %q 的明细 %q 分段与计价规则不符", key, ln.UsageID)
897			}
898			if ln.LineFee != priced.lines[i].fee {
899				return fmt.Errorf("账单 %q 的明细 %q 小计与计价规则不符", key, ln.UsageID)
900			}
901		}
902		for i, tt := range b.TierTotals {
903			if tt.Quantity != priced.tierQty[i] || tt.Fee != priced.tierFee[i] {
904				return fmt.Errorf("账单 %q 的第 %d 档合计与计价规则不符", key, i+1)
905			}
906		}
907		// 原总金额 = 月费 + 全月用量费；月费不进入分档合计与逐条小计。
908		wantTotal, err := add64(priced.totalFee, b.MonthlyFee)
909		if err != nil || wantTotal != b.TotalFee {
910			return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费", key)
911		}
912		return nil
913	}
