1086	// paymentsEverFor 返回历史上曾涉及某客户某月账单的全部收款（首次登记
1087	// 分配或任一次更正的新分配涉及该月，即使后来被更正移出），按操作序号升序。
1088	func paymentsEverFor(s *state, customerID, month string) []*payment {
1089		var list []*payment
1090		for _, p := range s.Payments {
1091			if p.CustomerID != customerID {
1092				continue
1093			}
1094			involved := p.amountFor(month) > 0
1095			if !involved {
1096				for _, c := range s.Corrections {
1097					if c.PaymentID == p.ID && allocAmountFor(c.Allocations, month) > 0 {
1098						involved = true
1099						break
1100					}
1101				}
1102			}
1103			if involved {
1104				list = append(list, p)
1105			}
1106		}
1107		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1108		return list
1109	}
