1111	// paymentReceived 返回全部未撤销收款按最新分配在指定月份计入的实收之和。
1112	// 各笔分配均为正整数，用非负 64 位加法累加，溢出时返回错误。
1113	func paymentReceived(s *state, customerID, month string) (int64, error) {
1114		var received int64
1115		for _, p := range s.Payments {
1116			if p.CustomerID != customerID || p.Revoked {
1117				continue
1118			}
1119			amt := allocAmountFor(currentAllocations(s, p), month)
1120			if amt <= 0 {
1121				continue
1122			}
1123			var err error
1124			received, err = add64(received, amt)
1125			if err != nil {
1126				return 0, err
1127			}
1128		}
1129		return received, nil
1130	}
1131	
1132	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
1133	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
1134	
1135	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
1136	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
1137	// [0, 有符号 64 位最大值] 内，全程整数运算。
1138	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
1139		var amounts []int64
1140		for _, a := range adjs {
1141			if !a.Revoked {
1142				amounts = append(amounts, a.Amount)
1143			}
1144		}
1145		net, err = sumSigned64(amounts...)
1146		if err != nil {
1147			return 0, 0, err
1148		}
1149		payable, err = addSigned64(b.TotalFee, net)
1150		if err != nil {
1151			return 0, 0, err
1152		}
1153		if payable < 0 {
1154			return 0, 0, errPayableOutOfRange
1155		}
1156		return net, payable, nil
1157	}
1158

