219		}
220		if _, exists := s.Customers[id]; exists {
221			return fmt.Errorf("客户标识 %q 已存在，客户单价创建后不可修改", id)
222		}
223		s.Customers[id] = &customer{ID: id, Name: name, Price: price}
224		if err := s.save(); err != nil {
225			return err
226		}
227		fmt.Fprintf(stdout, "已登记客户 %q（%s），固定单价 %d 分（%s）\n", id, name, price, moneyFen(price))
228		return nil
229	}
