231	func parsePrice(text string) (int64, error) {
232		text = strings.TrimSpace(text)
233		price, err := strconv.ParseInt(text, 10, 64)
234		if err != nil {
235			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
236		}
237		if price < 0 {
238			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
239		}
240		return price, nil
241	}
