243	// parsedRow 是导入文件中一行解析后的候选用量。
244	type parsedRow struct {
245		line int // 文件中的行号（含表头），用于报错定位
246		rec  usageRecord
247		t    time.Time
248	}
249	
250	func cmdUsageImport(dir, file string) error {
251		var reader io.ReadCloser
252		var source string
253		if file == "-" {
254			reader = io.NopCloser(os.Stdin)
255			source = "标准输入"
256		} else {
257			f, err := os.Open(file)
258			if err != nil {
259				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
260			}
261			reader = f
262			source = file
263		}
264		defer reader.Close()
265	
266		rows, parseErrs := parseUsageFile(reader)
267	
268		s, err := loadStore(dir)
269		if err != nil {
270			return err
271		}
272	
273		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
274		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
275		var problems []string
276		problems = append(problems, parseErrs...)
277	
278		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
279		var ordered []*parsedRow
280		newCount, dupCount := 0, 0
281	
282		for _, r := range rows {
283			cust, ok := s.Customers[r.rec.CustomerID]
284			if !ok {
285				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
286				continue
287			}
288	
289			// 去重判定同时对“库中已有”和“本文件内已出现”生效，且先于暂停、
290			// 封账与金额预检：已存在记录（含已撤回记录）按客户、解析后的时间点
291			// 和数量与原内容判重，相同重放计入重复跳过——即使该月后来已封账、
292			// 暂停或后续方案计价会溢出也不受阻；已撤回记录的重放不会恢复记录。
293			var existing *usageRecord
294			if inStore, ok := s.Usage[r.rec.ID]; ok {
295				existing = inStore
296			} else if inBatch, ok := accepted[r.rec.ID]; ok {
297				existing = &inBatch.rec
298			}
299			if existing != nil {
300				if !sameUsage(existing, &r.rec, r.t) {
301					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
302						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
303					continue
304				}
305				dupCount++
306				continue
307			}
308	
309			// 以下为全新用量：暂停、封账及当前方案下金额预检只约束全新用量。
310			// 暂停月的新用量一律拒绝：按记录时间换算的 UTC 月份判断，处于任一
311			// 暂停区间（含起月、不含结束月）即整批失败并指出行号。
312			rowMonth := r.t.UTC().Format("2006-01")
313			if s.isSuspendedMonth(r.rec.CustomerID, rowMonth) {
314				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 处于暂停区间，暂停服务期间不接收用量（新用量 %q 被拒绝）",
315					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
316				continue
317			}
318			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
319			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
320			// 溢出（金额单位：分）。
321			if cust.PlanID == "" {
322				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
323					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
324					continue
325				}
326			} else {
327				rec := r.rec
328				planID := s.effectivePlanID(cust, rowMonth)
329				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
330					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, rowMonth, planID, err))
331					continue
332				}
333			}
334	
335			// 全新标识：不得进入该客户已封账的 UTC 自然月。
336			if s.sealed(r.rec.CustomerID, rowMonth) {
337				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
338					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
339				continue
340			}
341	
342			rr := r
343			accepted[r.rec.ID] = rr
344			ordered = append(ordered, rr)
345			newCount++
346		}
347	
348		if len(problems) > 0 {
349			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
350		}
351	
352		for _, r := range ordered {
353			rec := r.rec
354			s.Usage[rec.ID] = &rec
355		}
356		if err := s.save(); err != nil {
357			return err
358		}
359		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
360		return nil
361	}
362	
363	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
364	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
365		cr := csv.NewReader(r)
366		cr.FieldsPerRecord = 4
367		cr.TrimLeadingSpace = true
368	
369		header, err := cr.Read()
370		if err == io.EOF {
371			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
372		}
373		if err != nil {
374			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
375		}
376		for i := range header {
377			header[i] = strings.TrimSpace(header[i])
378		}
379		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
380			header[2] != "time" || header[3] != "quantity" {
381			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
382		}
383	
384		var rows []*parsedRow
385		var problems []string
386		line := 1
387		for {
388			rec, err := cr.Read()
389			if err == io.EOF {
390				break
391			}
392			line++
393			if err != nil {
394				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
395				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
396					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
397					break
398				}
399				continue
400			}
401			for i := range rec {
402				rec[i] = strings.TrimSpace(rec[i])
403			}
404	
405			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
406			if id == "" {
407				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
408				continue
409			}
410			if custID == "" {
411				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
412				continue
413			}
414			t, err := time.Parse(time.RFC3339, ts)
415			if err != nil {
416				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
417				continue
418			}
419			qty, err := strconv.ParseInt(qtyText, 10, 64)
420			if err != nil {
421				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
422				continue
423			}
424			if qty <= 0 {
425				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
426				continue
427			}
428	
429			rows = append(rows, &parsedRow{
430				line: line,
431				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
432				t:    t,
433			})
434		}
435		return rows, problems
436	}
437	
438	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
439	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
440	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
441		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
442			return false
443		}
444		et, err := time.Parse(time.RFC3339, existing.Time)
445		if err != nil {
446			return existing.Time == candidate.Time
447		}
448		return et.Equal(candidateT)
449	}
450	
451	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
452	func validMonth(m string) bool {
453		t, err := time.Parse("2006-01", m)
454		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
455			return false
456		}
457		return true
458	}
459	
460	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
461	func inMonth(rfc3339, month string) bool {
462		t, err := time.Parse(time.RFC3339, rfc3339)
463		if err != nil {
464			return false
465		}
466		return t.UTC().Format("2006-01") == month
467	}
468	
469	// utcMonth 返回 RFC3339 时间换算 UTC 后的自然月（YYYY-MM）。
470	// 入参时间均已在载入/导入时校验为 RFC3339。
471	func utcMonth(rfc3339 string) string {
472		t, _ := time.Parse(time.RFC3339, rfc3339)
473		return t.UTC().Format("2006-01")
474	}
475	
476	func cmdBillSettle(dir, customerID, month string) error {
477		if !validMonth(month) {
478			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
479		}
480		s, err := loadStore(dir)
481		if err != nil {
482			return err
483		}
484		cust, ok := s.Customers[customerID]
485		if !ok {
486			return fmt.Errorf("客户标识 %q 不存在", customerID)
487		}
488	
489		// 暂停月无论方案月费多少都拒绝结算：不封账、不生成零金额账单。
490		if s.isSuspendedMonth(customerID, month) {
491			return fmt.Errorf("客户 %s 的 %s 处于暂停区间，暂停服务期间不产生月费账单，拒绝结算且不封账", customerID, month)
492		}
493	
494		key := billKey(customerID, month)
495		if existing, ok := s.Bills[key]; ok {
496			// 幂等：同一客户同一月份重复结算，直接返回原账单，
497			// 不重新计费、不产生新账单或调整、不落盘。
498			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
499			printBill(existing, cust, s)
500			return nil
501		}
502	
503		// 归集该客户 UTC 自然月内的全部有效（未撤回）用量，区间为左闭右开
504		// [月初, 下月初)。有效方案月费大于 0 的阶梯客户即使无用量也须出账
505		// （收取一次整月月费）；月费为 0 的方案与固定单价客户无用量时仍拒绝
506		// 结算且不封账。
507		inMonthRecs := monthUsage(s, customerID, month)
508		if len(inMonthRecs) == 0 && !monthlyFeeBillable(s, cust, month) {
509			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
510		}
511	
512		// 绑定阶梯方案的客户走按月累计分档计价；固定单价客户保持原路径。
513		if cust.PlanID != "" {
514			return settleTiered(s, cust, month, inMonthRecs)
515		}
516	
517		b, err := buildFixedBill(cust, month, inMonthRecs)
518		if err != nil {
519			return fmt.Errorf("%v，拒绝结算且不封账", err)
520		}
521		s.Bills[key] = b
522	
523		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
524		if err := s.save(); err != nil {
525			delete(s.Bills, key)
526			return err
527		}
528		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
529		printBill(b, cust, s)
530		return nil
531	}
