553	// monthUsage 归集客户在某 UTC 自然月（左闭右开 [月初, 下月初)）内的全部
554	// 有效（未撤回）用量，并按计价顺序（解析后的时间点升序、同一时间按标识
555	// 字典序）排列。已撤回用量不计费用，不参与单笔及批量结算；阶梯计价将剩余
556	// 记录按原有时间点及标识顺序从零累计重新分档。
557	func monthUsage(s *state, customerID, month string) []*usageRecord {
558		var recs []*usageRecord
559		for _, u := range s.Usage {
560			if s.isWithdrawn(u.ID) {
561				continue
562			}
563			if u.CustomerID == customerID && inMonth(u.Time, month) {
564				recs = append(recs, u)
565			}
566		}
567		sortByInstant(recs)
568		return recs
569	}
570	
571	// buildFixedBill 为固定单价客户构造账单（不落盘）：逐条 数量×单价 并汇总，
572	// 全程整数运算，任何一步溢出都返回错误。recs 须已按计价顺序排列。
573	func buildFixedBill(cust *customer, month string, recs []*usageRecord) (*bill, error) {
574		lines := make([]billLine, 0, len(recs))
575		var totalQty, totalFee int64
576		for _, u := range recs {
577			lineFee, err := mul64(u.Quantity, cust.Price)
578			if err != nil {
579				return nil, fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出", u.ID, u.Quantity, cust.Price)
580			}
581			if totalQty, err = add64(totalQty, u.Quantity); err != nil {
582				return nil, fmt.Errorf("汇总数量溢出有符号 64 位整数范围")
583			}
584			if totalFee, err = add64(totalFee, lineFee); err != nil {
585				return nil, fmt.Errorf("汇总金额溢出有符号 64 位整数范围")
586			}
587			lines = append(lines, billLine{
588				UsageID:  u.ID,
589				Time:     u.Time,
590				Quantity: u.Quantity,
591				LineFee:  lineFee,
592			})
593		}
594		return &bill{
595			ID:         stableBillID(cust.ID, month),
596			CustomerID: cust.ID,
597			Month:      month,
598			TotalQty:   totalQty,
599			UnitPrice:  cust.Price,
600			TotalFee:   totalFee,
601			Lines:      lines,
602			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
603		}, nil
604	}
605	
606	func sortByInstant(us []*usageRecord) {
607		// 入参时间均已在载入/导入时校验为 RFC3339。
608		sort.Slice(us, func(i, j int) bool {
609			ti, _ := time.Parse(time.RFC3339, us[i].Time)
610			tj, _ := time.Parse(time.RFC3339, us[j].Time)
611			ui, uj := ti.UTC(), tj.UTC()
612			if !ui.Equal(uj) {
613				return ui.Before(uj)
614			}
615			return us[i].ID < us[j].ID
616		})
617	}
618	
619	// stableBillID 由（客户标识，月份）确定性派生：跨进程稳定，且客户/月份间唯一。
620	func stableBillID(customerID, month string) string {
621		sum := sha256.Sum256([]byte(customerID + "\x00" + month))
622		return "BILL-" + hex.EncodeToString(sum[:])[:16]
623	}
624	
625	func printBill(b *bill, cust *customer, s *state) {
626		adjs := adjustmentsFor(s, b.CustomerID, b.Month)
627		// 收款历史保留所有曾涉及本账单的收款：首次登记或任一次更正分配
628		// 涉及该月即纳入，即使后来被更正移出。
629		pays := paymentsEverFor(s, b.CustomerID, b.Month)
630		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
631		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
632		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
633		tiered := b.Pricing == "tiered"
634		if tiered {
635			// 阶梯账单明确计价类型并展示方案与完整规则，不伪造统一单价。
636			fmt.Fprintf(stdout, "计价类型：阶梯计费（按 UTC 自然月累计用量分档计价，每月从零累计）\n")
637			fmt.Fprintf(stdout, "方案：%s（%s）\n", b.PlanID, b.PlanName)
638			fmt.Fprintln(stdout, "阶梯规则：")
639			for i, t := range b.PlanTiers {
640				if t.Limit == 0 {
641					fmt.Fprintf(stdout, "  第 %d 档：累计数量无上限，单价 %d 分（%s）\n", i+1, t.Price, moneyFen(t.Price))
642				} else {
643					fmt.Fprintf(stdout, "  第 %d 档：累计上限 %d，单价 %d 分（%s）\n", i+1, t.Limit, t.Price, moneyFen(t.Price))
644				}
645			}
646		} else {
647			fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
648		}
649		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
650		if tiered {
651			// 阶梯账单分列月费与用量费：原总金额 = 月费 + 全月用量费；
652			// 月费不计入总数量、各档金额或逐条小计。
653			usageFee := b.TotalFee - b.MonthlyFee
654			fmt.Fprintf(stdout, "月费：%d 分（%s，整月收取，不按天折算）\n", b.MonthlyFee, moneyFen(b.MonthlyFee))
655			fmt.Fprintf(stdout, "用量费：%d 分（%s）\n", usageFee, moneyFen(usageFee))
656			fmt.Fprintf(stdout, "原总金额：%d 分（%s，月费加全月用量费）\n", b.TotalFee, moneyFen(b.TotalFee))
657		} else {
658			fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
659		}
660		if tiered {
661			fmt.Fprintln(stdout, "各档合计：")
662			for i, tt := range b.TierTotals {
663				fmt.Fprintf(stdout, "  第 %d 档：数量 %d，单价 %d 分，金额 %d 分（%s）\n",
664					i+1, tt.Quantity, b.PlanTiers[i].Price, tt.Fee, moneyFen(tt.Fee))
665			}
666		}
667		// 数据在载入时已校验一致，此处计算不会出错。
668		net, payable, _ := billTotals(b, adjs)
669		received, _ := paymentReceived(s, b.CustomerID, b.Month)
670		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
671		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
672		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
673		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
674		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
675		if len(b.Lines) == 0 {
676			fmt.Fprintln(stdout, "明细：无（本账期无用量，仅收取月费）")
677		} else {
678			fmt.Fprintln(stdout, "明细：")
679		}
680		for i, ln := range b.Lines {
681			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
682				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
683			// 阶梯账单逐条展示跨档分段的数量、单价与小计。
684			for j, seg := range ln.Segments {
685				fmt.Fprintf(stdout, "     分段 %d：第 %d 档 数量=%d 单价=%d 分 小计=%d 分（%s）\n",
686					j+1, seg.Tier+1, seg.Quantity, b.PlanTiers[seg.Tier].Price, seg.Fee, moneyFen(seg.Fee))
687			}
688		}
689		if len(adjs) == 0 {
690			fmt.Fprintln(stdout, "调整与撤销历史：无")
691		} else {
692			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
693			for i, ev := range historyEvents(adjs) {
694				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
695			}
696		}
697		if len(pays) == 0 {
698			fmt.Fprintln(stdout, "收款与撤销历史：无")
699		} else {
700			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
701			for i, ev := range paymentHistoryEvents(s, pays, b.Month) {
702				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
703			}
704		}
705	}
