707	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
708	func historyEvents(adjs []*adjustment) []string {
709		type event struct {
710			seq  int64
711			text string
712		}
713		var events []event
714		for _, a := range adjs {
715			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
716				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
717			if a.Revoked {
718				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
719					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
720			}
721		}
722		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
723		out := make([]string, len(events))
724		for i, ev := range events {
725			out[i] = ev.text
726		}
727		return out
728	}
