744	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
745	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
746	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
747	// 的最新分配。
748	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
749		type event struct {
750			seq  int64
751			text string
752		}
753		var events []event
754		for _, p := range pays {
755			alloc := p.amountFor(month)
756			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
757				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
758			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
759			running := alloc
760			for _, c := range correctionsFor(s, p.ID) {
761				after := allocAmountFor(c.Allocations, month)
762				if running == 0 && after == 0 {
763					continue // 本次更正不涉及本账单
764				}
765				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
766					c.ID, c.Reason, p.ID, running, after)})
767				running = after
768			}
769			if p.Revoked {
770				// 整笔撤销取消的是撤销时的最新分配。
771				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
772					p.ID, p.RevokeReason, p.ID, p.Total, running)})
773			}
774		}
775		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
776		out := make([]string, len(events))
777		for i, ev := range events {
778			out[i] = ev.text
779		}
780		return out
781	}
