803	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
804		if !validMonth(month) {
805			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
806		}
807		if strings.TrimSpace(adjID) == "" {
808			return fmt.Errorf("调整标识不能为空")
809		}
810		amount, err := parseAmount(amountText)
811		if err != nil {
812			return err
813		}
814		if strings.TrimSpace(reason) == "" {
815			return fmt.Errorf("调整原因不能为空")
816		}
817	
818		s, err := loadStore(dir)
819		if err != nil {
820			return err
821		}
822		if _, ok := s.Customers[customerID]; !ok {
823			return fmt.Errorf("客户标识 %q 不存在", customerID)
824		}
825		b, ok := s.Bills[billKey(customerID, month)]
826		if !ok {
827			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
828		}
829	
830		if existing, ok := s.Adjustments[adjID]; ok {
831			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
832			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
833			if existing.CustomerID == customerID && existing.Month == month &&
834				existing.Amount == amount && existing.Reason == reason {
835				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
836				printAdjustment(existing, s)
837				return nil
838			}
839			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
840				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
841		}
842	
843		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
844		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
845		// 不占用该调整标识。
846		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
847		if err != nil {
848			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
849		}
850		received, err := paymentReceived(s, customerID, month)
851		if err != nil {
852			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
853		}
854		newPayable, err := addSigned64(payable, amount)
855		if err != nil {
856			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
857		}
858		if newPayable < 0 {
859			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
860		}
861		if newPayable < received {
862			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
863				newPayable, received, payable, amount)
864		}
865	
866		a := &adjustment{
867			ID:         adjID,
868			CustomerID: customerID,
869			Month:      month,
870			Amount:     amount,
871			Reason:     reason,
872			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
873		}
874		s.NextSeq++
875		a.Seq = s.NextSeq
876		s.Adjustments[adjID] = a
877	
878		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
879		// 该调整标识不被占用。
880		if err := s.save(); err != nil {
881			delete(s.Adjustments, adjID)
882			s.NextSeq--
883			return err
884		}
885		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
886			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
887		printAdjustment(a, s)
888		return nil
889	}
