891	func cmdBillRevoke(dir, adjID, reason string) error {
892		if strings.TrimSpace(adjID) == "" {
893			return fmt.Errorf("调整标识不能为空")
894		}
895		if strings.TrimSpace(reason) == "" {
896			return fmt.Errorf("撤销原因不能为空")
897		}
898	
899		s, err := loadStore(dir)
900		if err != nil {
901			return err
902		}
903		a, ok := s.Adjustments[adjID]
904		if !ok {
905			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
906		}
907	
908		if a.Revoked {
909			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
910			// 改用其他原因则拒绝。
911			if a.RevokeReason == reason {
912				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
913				printAdjustment(a, s)
914				return nil
915			}
916			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
917		}
918	
919		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
920		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
921		// 改变余额后重试。
922		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
923		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
924		if err != nil {
925			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
926		}
927		received, err := paymentReceived(s, a.CustomerID, a.Month)
928		if err != nil {
929			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
930		}
931		neg, err := neg64(a.Amount)
932		if err != nil {
933			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
934		}
935		newPayable, err := addSigned64(payable, neg)
936		if err != nil {
937			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
938				payable, a.Amount)
939		}
940		if newPayable < 0 {
941			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
942				newPayable, payable, a.Amount)
943		}
944		if newPayable < received {
945			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
946				newPayable, received, payable, a.Amount)
947		}
948	
949		a.Revoked = true
950		a.RevokeReason = reason
951		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
952		s.NextSeq++
953		a.RevokeSeq = s.NextSeq
954	
955		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
956		if err := s.save(); err != nil {
957			a.Revoked = false
958			a.RevokeReason = ""
959			a.RevokedAt = ""
960			a.RevokeSeq = 0
961			s.NextSeq--
962			return err
963		}
964		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
965			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
966		printAdjustment(a, s)
967		return nil
968	}
