970	// printAdjustment 输出单笔调整记录及其当前状态；payable 取自当前库状态。
971	func printAdjustment(a *adjustment, s *state) {
972		b := s.Bills[billKey(a.CustomerID, a.Month)]
973		_, payable, _ := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
974		fmt.Fprintf(stdout, "调整标识：%s\n", a.ID)
975		fmt.Fprintf(stdout, "客户：%s\n", a.CustomerID)
976		fmt.Fprintf(stdout, "月份：%s\n", a.Month)
977		fmt.Fprintf(stdout, "调整金额：%+d 分（%s，%s）\n", a.Amount, moneyFen(a.Amount), adjustKind(a.Amount))
978		fmt.Fprintf(stdout, "原因：%s\n", a.Reason)
979		if a.Revoked {
980			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", a.RevokeReason)
981		} else {
982			fmt.Fprintf(stdout, "当前状态：生效中\n")
983		}
984		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
985	}
