1000	func cmdBillPay(dir, customerID, month, payID, amountText, note string) error {
1001		if !validMonth(month) {
1002			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1003		}
1004		amount, err := parsePositiveAmount(amountText)
1005		if err != nil {
1006			return err
1007		}
1008		// 单账单收款视为只有一项分配的汇款，与 bill remit 共用同一核心。
1009		return registerPayment(dir, customerID, payID, amount, note,
1010			[]paymentAllocation{{Month: month, Amount: amount}})
1011	}
1012	
1013	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
1014		total, err := parsePositiveAmount(totalText)
1015		if err != nil {
1016			return err
1017		}
1018		allocs, err := parseAllocations(allocArgs)
1019		if err != nil {
1020			return err
1021		}
1022		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
1023		var sum int64
1024		for _, al := range allocs {
1025			sum, err = add64(sum, al.Amount)
1026			if err != nil {
1027				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
1028			}
1029		}
1030		if sum != total {
1031			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
1032		}
1033		return registerPayment(dir, customerID, payID, total, note, allocs)
1034	}
1035	
1036	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
1037	// 月份不得重复，每项金额为正整数分。
1038	func parseAllocations(args []string) ([]paymentAllocation, error) {
1039		if len(args) == 0 {
1040			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
1041		}
1042		seen := make(map[string]bool)
1043		allocs := make([]paymentAllocation, 0, len(args))
1044		for _, arg := range args {
1045			parts := strings.Split(arg, ":")
1046			if len(parts) != 2 {
1047				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
1048			}
1049			month := strings.TrimSpace(parts[0])
1050			if !validMonth(month) {
1051				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
1052			}
1053			if seen[month] {
1054				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
1055			}
1056			seen[month] = true
1057			amount, err := parsePositiveAmount(parts[1])
1058			if err != nil {
1059				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
1060			}
1061			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
1062		}
1063		return allocs, nil
1064	}
1065	
1066	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
1067	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
1068	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
1069		if strings.TrimSpace(payID) == "" {
1070			return fmt.Errorf("收款标识不能为空")
1071		}
1072		if strings.TrimSpace(note) == "" {
1073			return fmt.Errorf("收款备注不能为空")
1074		}
1075		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
1076		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1077	
1078		s, err := loadStore(dir)
1079		if err != nil {
1080			return err
1081		}
1082		if _, ok := s.Customers[customerID]; !ok {
1083			return fmt.Errorf("客户标识 %q 不存在", customerID)
1084		}
1085		for _, al := range allocs {
1086			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
1087				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
1088			}
1089		}
1090	
1091		if existing, ok := s.Payments[payID]; ok {
1092			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
1093			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
1094			// 已撤销的重放仍返回已撤销状态，不恢复实收。
1095			if samePaymentContent(existing, customerID, total, note, allocs) {
1096				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
1097				printPayment(existing, s)
1098				return nil
1099			}
1100			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
1101				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1102		}
1103	
1104		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1105		for _, al := range allocs {
1106			b := s.Bills[billKey(customerID, al.Month)]
1107			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1108			if err != nil {
1109				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1110			}
1111			received, err := paymentReceived(s, customerID, al.Month)
1112			if err != nil {
1113				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1114			}
1115			if payable == 0 {
1116				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1117			}
1118			if al.Amount > payable-received {
1119				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1120					al.Amount, payable-received, customerID, al.Month, payable, received)
1121			}
1122		}
1123	
1124		p := &payment{
1125			ID:          payID,
1126			CustomerID:  customerID,
1127			Total:       total,
1128			Note:        note,
1129			Allocations: allocs,
1130			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1131		}
1132		s.NextSeq++
1133		p.Seq = s.NextSeq
1134		s.Payments[payID] = p
1135	
1136		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1137		// 一切不生效，该收款标识不被占用。
1138		if err := s.save(); err != nil {
1139			delete(s.Payments, payID)
1140			s.NextSeq--
1141			return err
1142		}
1143		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1144		printAllocationBalances(s, p, allocs)
1145		fmt.Fprintln(stdout)
1146		printPayment(p, s)
1147		return nil
1148	}
1149	
1150	// samePaymentContent 按客户、总额、备注与月份-金额对应关系判定两笔收款
1151	// 内容相同；分配顺序不影响身份。判重依据首次登记内容，不受后续更正影响。
1152	func samePaymentContent(p *payment, customerID string, total int64, note string, allocs []paymentAllocation) bool {
1153		if p.CustomerID != customerID || p.Total != total || p.Note != note {
1154			return false
1155		}
1156		return sameAllocations(p.Allocations, allocs)
1157	}
1158	
1159	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1160	func sameAllocations(a, b []paymentAllocation) bool {
1161		if len(a) != len(b) {
1162			return false
1163		}
1164		for _, al := range b {
1165			if allocAmountFor(a, al.Month) != al.Amount {
1166				return false
1167			}
1168		}
1169		return true
1170	}
1171	
1172	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1173	func formatAllocations(allocs []paymentAllocation) string {
1174		parts := make([]string, len(allocs))
1175		for i, al := range allocs {
1176			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1177		}
1178		return strings.Join(parts, ",")
1179	}
