1192	func cmdBillUnpay(dir, payID, reason string) error {
1193		if strings.TrimSpace(payID) == "" {
1194			return fmt.Errorf("收款标识不能为空")
1195		}
1196		if strings.TrimSpace(reason) == "" {
1197			return fmt.Errorf("撤销原因不能为空")
1198		}
1199	
1200		s, err := loadStore(dir)
1201		if err != nil {
1202			return err
1203		}
1204		p, ok := s.Payments[payID]
1205		if !ok {
1206			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1207		}
1208	
1209		if p.Revoked {
1210			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1211			// 改用其他原因则拒绝。
1212			if p.RevokeReason == reason {
1213				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1214				printPayment(p, s)
1215				return nil
1216			}
1217			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1218		}
1219	
1220		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1221		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1222		// 分配、更正与撤销原因永久保留。
1223		p.Revoked = true
1224		p.RevokeReason = reason
1225		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1226		s.NextSeq++
1227		p.RevokeSeq = s.NextSeq
1228	
1229		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1230		if err := s.save(); err != nil {
1231			p.Revoked = false
1232			p.RevokeReason = ""
1233			p.RevokedAt = ""
1234			p.RevokeSeq = 0
1235			s.NextSeq--
1236			return err
1237		}
1238		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1239		printAllocationBalances(s, p, currentAllocations(s, p))
1240		fmt.Fprintln(stdout)
1241		printPayment(p, s)
1242		return nil
1243	}
1244	
1245	// printPayment 输出单笔收款记录：总额、首次登记的全部分配（永久保留，
1246	// 判重依据）与当前状态；经历过更正时同时展示当前生效的最新分配。
1247	// 各月应付/实收取自当前库状态。
1248	func printPayment(p *payment, s *state) {
1249		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1250		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1251		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1252		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1253		if p.Revoked {
1254			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1255		} else {
1256			fmt.Fprintf(stdout, "当前状态：实收中\n")
1257		}
1258		fmt.Fprintln(stdout, "分配明细（首次登记，永久保留）：")
1259		for i, al := range p.Allocations {
1260			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1261			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1262			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1263			fmt.Fprintf(stdout, "  %d. 月份 %s：分配 %d 分（%s）；当前应付 %d 分，实收合计 %d 分，未收余额 %d 分\n",
1264				i+1, al.Month, al.Amount, moneyFen(al.Amount), payable, received, payable-received)
1265		}
1266		if corrs := correctionsFor(s, p.ID); len(corrs) > 0 {
1267			fmt.Fprintf(stdout, "当前分配（经 %d 次更正，以最新为准）：%s\n",
1268				len(corrs), formatAllocations(currentAllocations(s, p)))
1269		}
1270	}
