1272	// --- 收款分配更正 ---
1273	
1274	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1275		if strings.TrimSpace(payID) == "" {
1276			return fmt.Errorf("收款标识不能为空")
1277		}
1278		if strings.TrimSpace(corrID) == "" {
1279			return fmt.Errorf("更正标识不能为空")
1280		}
1281		if strings.TrimSpace(reason) == "" {
1282			return fmt.Errorf("更正原因不能为空")
1283		}
1284		allocs, err := parseAllocations(allocArgs)
1285		if err != nil {
1286			return err
1287		}
1288		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1289		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1290	
1291		s, err := loadStore(dir)
1292		if err != nil {
1293			return err
1294		}
1295		p, ok := s.Payments[payID]
1296		if !ok {
1297			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1298		}
1299	
1300		if existing, ok := s.Corrections[corrID]; ok {
1301			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1302			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1303			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1304			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1305				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1306				printCorrection(existing, s)
1307				return nil
1308			}
1309			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1310				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1311		}
1312	
1313		// 新增更正只允许未撤销收款。
1314		if p.Revoked {
1315			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1316		}
1317	
1318		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1319		var sum int64
1320		for _, al := range allocs {
1321			sum, err = add64(sum, al.Amount)
1322			if err != nil {
1323				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1324			}
1325		}
1326		if sum != p.Total {
1327			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1328		}
1329		// 新分配月份须是原客户的已结算账单。
1330		for _, al := range allocs {
1331			if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
1332				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到已存在账单", p.CustomerID, al.Month)
1333			}
1334		}
1335	
1336		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1337		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1338		current := currentAllocations(s, p)
1339		for _, m := range unionMonths(current, allocs) {
1340			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1341			_, payable, err := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1342			if err != nil {
1343				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", p.CustomerID, m, err)
1344			}
1345			received, err := paymentReceived(s, p.CustomerID, m)
1346			if err != nil {
1347				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", p.CustomerID, m, err)
1348			}
1349			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1350			received -= allocAmountFor(current, m)
1351			received, err = add64(received, allocAmountFor(allocs, m))
1352			if err != nil {
1353				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", p.CustomerID, m)
1354			}
1355			if received > payable {
1356				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1357					p.CustomerID, m, received, payable)
1358			}
1359		}
1360	
1361		c := &correction{
1362			ID:          corrID,
1363			PaymentID:   payID,
1364			Reason:      reason,
1365			Allocations: allocs,
1366			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1367		}
1368		s.NextSeq++
1369		c.Seq = s.NextSeq
1370		s.Corrections[corrID] = c
1371	
1372		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1373		// 一切不生效，该更正标识不被占用。
1374		if err := s.save(); err != nil {
1375			delete(s.Corrections, corrID)
1376			s.NextSeq--
1377			return err
1378		}
1379		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1380		printCorrection(c, s)
1381		return nil
1382	}
1383	
1384	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1385	func unionMonths(a, b []paymentAllocation) []string {
1386		set := make(map[string]bool, len(a)+len(b))
1387		for _, al := range a {
1388			set[al.Month] = true
1389		}
1390		for _, al := range b {
1391			set[al.Month] = true
1392		}
1393		months := make([]string, 0, len(set))
1394		for m := range set {
1395			months = append(months, m)
1396		}
1397		sort.Strings(months)
1398		return months
1399	}
1400	
1401	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1402	// 新分配，或（首次更正时）收款的原始分配。
1403	func allocationBefore(s *state, c *correction) []paymentAllocation {
1404		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1405		var latest *correction
1406		for _, o := range s.Corrections {
1407			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1408				latest = o
1409			}
1410		}
1411		if latest != nil {
1412			before = latest.Allocations
1413		}
1414		return before
1415	}
