1439	// --- 账后对账流水 ---
1440	
1441	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1442	// 分配更正或撤销收款。事件按全局操作序号升序回放；撤销在其发生序号抵消
1443	// 对应原操作，已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件；
1444	// 更正在其发生序号把关联收款在本账单的分配由前值替换为后值。
1445	type ledgerEvent struct {
1446		seq           int64  // 全局操作序号（调整/收款/更正及其撤销共用）
1447		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款
1448		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1449		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1450		deltaReceived int64  // 对实收的影响（分，带符号）
1451		note          string // 原因（调整/更正类）或备注（收款类）
1452		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1453		payTotal      int64  // 收款类事件：汇款总额
1454		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配）
1455		payID         string // 更正事件：关联收款标识
1456		beforeAlloc   int64  // 更正事件：本账单更正前分配
1457		afterAlloc    int64  // 更正事件：本账单更正后分配
1458		afterPayable  int64  // 事件后的应付（回放时填充）
1459		afterReceived int64  // 事件后的实收（回放时填充）
1460	}
1461	
1462	// billLedger 把目标账单的调整、调整撤销、收款、分配更正与收款撤销合并为
1463	// 一条按操作序号升序的流水，并以原总金额为初始应付、零实收为起点逐步回放，
1464	// 填充每个事件之后的三项余额。回放覆盖完整流水（不受查询截止序号限制）：
1465	// 序号重复、撤销先于原操作，或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号
1466	// 64 位最大值，都视为数据异常并拒绝——只检查最终余额会放过中间越界的存档。
1467	// 只读：不修改库、不占用序号、不新增记录。
1468	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1469		var events []ledgerEvent
1470		for _, a := range s.Adjustments {
1471			if a.CustomerID != b.CustomerID || a.Month != b.Month {
1472				continue
1473			}
1474			events = append(events, ledgerEvent{
1475				seq: a.Seq, kind: "调整", refID: a.ID,
1476				deltaPayable: a.Amount, note: a.Reason,
1477			})
1478			if a.Revoked {
1479				neg, err := neg64(a.Amount)
1480				if err != nil {
1481					return nil, fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出流水", a.ID, a.Amount)
1482				}
1483				events = append(events, ledgerEvent{
1484					seq: a.RevokeSeq, kind: "撤销调整", refID: a.ID,
1485					deltaPayable: neg, note: a.RevokeReason, linkSeq: a.Seq,
1486				})
1487			}
1488		}
1489		for _, p := range s.Payments {
1490			if p.CustomerID != b.CustomerID {
1491				continue
1492			}
1493			// 多月汇款只以本账单分配改变实收；更正在其发生序号把本账单分配
1494			// 由前值替换为后值；整笔撤销在同一序号取消撤销时的最新分配。
1495			// 首次登记或任一次更正涉及本账单的，该收款的后续事件都纳入流水。
1496			alloc := p.amountFor(b.Month)
1497			corrs := correctionsFor(s, p.ID)
1498			involved := alloc > 0
1499			if !involved {
1500				for _, c := range corrs {
1501					if allocAmountFor(c.Allocations, b.Month) > 0 {
1502						involved = true
1503						break
1504					}
1505				}
1506			}
1507			if !involved {
1508				continue
1509			}
1510			if alloc > 0 {
1511				events = append(events, ledgerEvent{
1512					seq: p.Seq, kind: "收款", refID: p.ID,
1513					deltaReceived: alloc, note: p.Note,
1514					payTotal: p.Total, payAlloc: alloc,
1515				})
1516			}
1517			running := alloc
1518			for _, c := range corrs {
1519				after := allocAmountFor(c.Allocations, b.Month)
1520				if running == 0 && after == 0 {
1521					continue // 本次更正不涉及本账单
1522				}
1523				events = append(events, ledgerEvent{
1524					seq: c.Seq, kind: "更正", refID: c.ID,
1525					deltaReceived: after - running, note: c.Reason,
1526					payID: p.ID, beforeAlloc: running, afterAlloc: after,
1527				})
1528				running = after
1529			}
1530			if p.Revoked {
1531				events = append(events, ledgerEvent{
1532					seq: p.RevokeSeq, kind: "撤销收款", refID: p.ID,
1533					deltaReceived: -running, note: p.RevokeReason, linkSeq: p.Seq,
1534					payTotal: p.Total, payAlloc: running,
1535				})
1536			}
1537		}
1538		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
1539	
1540		// 逐步回放并核验：只把每个事件的金额影响加到运行余额上，不对发生额
1541		// 做累计求和，因此累计补收/收款发生额超过 64 位上限但每步余额合法时
1542		// 仍能成功。
1543		payable := b.TotalFee
1544		var received int64
1545		seen := make(map[int64]string, len(events))
1546		for i := range events {
1547			ev := &events[i]
1548			desc := ev.kind + " " + ev.refID
1549			if prev, dup := seen[ev.seq]; dup {
1550				return nil, fmt.Errorf("流水序号 %d 重复（%s 与 %s），数据异常，拒绝输出流水", ev.seq, prev, desc)
1551			}
1552			seen[ev.seq] = desc
1553			if ev.linkSeq != 0 && ev.linkSeq >= ev.seq {
1554				return nil, fmt.Errorf("%s 的撤销序号 %d 不晚于原操作序号 %d，数据异常，拒绝输出流水", desc, ev.seq, ev.linkSeq)
1555			}
1556			var err error
1557			if payable, err = addSigned64(payable, ev.deltaPayable); err != nil {
1558				return nil, fmt.Errorf("序号 %d（%s）之后应付越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1559			}
1560			if received, err = addSigned64(received, ev.deltaReceived); err != nil {
1561				return nil, fmt.Errorf("序号 %d（%s）之后实收越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1562			}
1563			if payable < 0 {
1564				return nil, fmt.Errorf("序号 %d（%s）之后应付为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, payable)
1565			}
1566			if received < 0 {
1567				return nil, fmt.Errorf("序号 %d（%s）之后实收为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, received)
1568			}
1569			if received > payable {
1570				return nil, fmt.Errorf("序号 %d（%s）之后实收 %d 分超过应付 %d 分，数据异常，拒绝输出流水", ev.seq, desc, received, payable)
1571			}
1572			ev.afterPayable = payable
1573			ev.afterReceived = received
1574		}
1575		return events, nil
1576	}
1577	
1578	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1579		if !validMonth(month) {
1580			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1581		}
1582		s, err := loadStore(dir)
1583		if err != nil {
1584			return err
1585		}
1586		cust, ok := s.Customers[customerID]
1587		if !ok {
1588			return fmt.Errorf("客户标识 %q 不存在", customerID)
1589		}
1590		b, ok := s.Bills[billKey(customerID, month)]
1591		if !ok {
1592			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1593		}
1594	
1595		// 截止序号使用调整/收款及其撤销共用的已保存全局序号：省略表示最新，
1596		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1597		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1598		cutoff := s.NextSeq
1599		cutoffDesc := "省略，按最新"
1600		if hasCutoff {
1601			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1602			if perr != nil {
1603				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1604			}
1605			if v < 0 {
1606				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1607			}
1608			if v > s.NextSeq {
1609				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1610			}
1611			cutoff = v
1612			cutoffDesc = "指定"
1613		}
1614	
1615		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1616		// 拒绝，不输出部分正常的报告。
1617		events, err := billLedger(s, b)
1618		if err != nil {
1619			return err
1620		}
1621		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1622		return nil
1623	}
1624	
1625	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1626		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1627		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1628		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1629		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1630		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1631		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1632		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1633			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1634	
1635		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1636		payable, received := b.TotalFee, int64(0)
1637		var shown []ledgerEvent
1638		for _, ev := range events {
1639			if ev.seq > cutoff {
1640				continue
1641			}
1642			shown = append(shown, ev)
1643			payable, received = ev.afterPayable, ev.afterReceived
1644		}
1645		if len(shown) == 0 {
1646			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1647		} else {
1648			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1649			for i, ev := range shown {
1650				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1651			}
1652		}
1653		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1654			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1655	}
1656	
1657	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1658	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1659	// 说明汇款总额与本账单分配。
1660	func formatLedgerEvent(ev ledgerEvent) string {
1661		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1662			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1663		switch ev.kind {
1664		case "调整":
1665			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1666				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1667		case "撤销调整":
1668			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1669				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1670		case "收款":
1671			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1672				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1673		case "更正":
1674			return fmt.Sprintf("序号 %d 更正 %s：实收 %+d 分（%s，关联收款 %s，本账单分配 %d 分 → %d 分），原因：%s → %s",
1675				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.beforeAlloc, ev.afterAlloc, ev.note, after)
1676		default: // 撤销收款
1677			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1678				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1679		}
1680	}
1681

