		t.Fatalf("区间外的操作混入报表:\n%s", out)
	}

	// 起点等于终点：变动区间为空，两端余额相同，无区间内操作。
	out = h.mustRun("bill", "report", "c1", "2026-09", "2026-10", "3", "3")
