		if !errors.As(err, &ue) {
			t.Fatalf("args=%v 应为用法错误(2)，得到 %v", args, err)
		}
	}
	// 失败后合法查询照常，存档不变。
	out = h.mustRun("bill", "report", "c1", "2026-09", "2026-09")
	if !strings.Contains(out, "选中账单：1 张") {
		t.Fatal(out)
	}
}

