11	// 跨账期对账报表（bill report）：只读命令，用一份报告核对一个客户多个账期
12	// 在一段账后操作中的余额变化。账单选择只看账期范围（含首尾）内当前已存在
13	// 的账单，不补结算、不按操作时间筛选；所有选中账单在序号 0 以原总金额为
14	// 应付、零实收起算，与 bill ledger 共用同一份流水回放，保证两端逐月余额
15	// 与相同截止的 bill ledger 一致、终点为最新时与 bill show 一致。
16	// 只读：不修改库、不占用序号、不新增记录，成功或失败均不改写存档。
17	
18	// reportBill 是报表中一张选中账单及其完整（已核验）账后流水。
19	type reportBill struct {
20		bill   *bill
21		events []ledgerEvent // 按全局操作序号升序，回放时已逐步核验
22	}
23	
24	// reportMonthDelta 是一次账后操作对范围内某个月账单的金额影响。
25	type reportMonthDelta struct {
26		month         string
27		deltaPayable  int64 // 对当前应付的影响（分，带符号）
28		deltaReceived int64 // 对实收的影响（分，带符号）
29		payAlloc      int64 // 收款/撤销收款事件：该月分配（撤销为被取消的最新分配）
30		beforeAlloc   int64 // 更正事件：该月更正前分配
31		afterAlloc    int64 // 更正事件：该月更正后分配
32	}
33	
34	// reportEvent 是报表中合并后的一次账后操作：同一全局序号的操作只展示一次，
35	// 范围内各月的变化合并到同一条目。调整与收款可同名，按类型分别关联。
36	type reportEvent struct {
37		seq      int64              // 全局操作序号
38		kind     string             // 调整 / 撤销调整 / 收款 / 更正 / 撤销收款
39		refID    string             // 原记录标识（调整标识、收款标识或更正标识）
40		note     string             // 原因（调整/更正类）或备注（收款类）
41		linkSeq  int64              // 撤销事件关联的原操作序号；非撤销事件为 0
42		payTotal int64              // 收款类事件：汇款总额
43		payID    string             // 更正事件：关联收款标识
44		months   []reportMonthDelta // 范围内各月变化，按月份升序
45	}
46	
47	// balanceAtSeq 返回账单流水在指定序号操作完成后的应付与实收：序号 0 为初始
48	// 余额（原总金额、零实收），截止包含该序号。events 须按序号升序。
49	func balanceAtSeq(b *bill, events []ledgerEvent, seq int64) (payable, received int64) {
50		payable, received = b.TotalFee, 0
51		for _, ev := range events {
52			if ev.seq > seq {
53				break
54			}
55			payable, received = ev.afterPayable, ev.afterReceived
56		}
57		return payable, received
58	}
59	
60	// allocTouchesRange 报告分配列表是否涉及账期范围 [startMonth, endMonth]
61	// （含首尾）内的月份；分配金额恒为正整数分。
62	func allocTouchesRange(allocs []paymentAllocation, startMonth, endMonth string) bool {
63		for _, al := range allocs {
64			if al.Month >= startMonth && al.Month <= endMonth {
65				return true
66			}
67		}
68		return false
69	}
70	
71	// mergeReportEvents 把各选中账单流水中的事件按全局序号合并：同一序号的操作
72	// 只保留一条，范围内各月变化并入 months。收款按登记时分配、收款撤销按撤销
73	// 发生时最新分配、更正按前后分配判断是否涉及范围——撤销时最新分配不含范围
74	// 内月份的收款撤销与本报表无关，不展示。
75	func mergeReportEvents(s *state, bills []*reportBill, startMonth, endMonth string) []reportEvent {
76		bySeq := make(map[int64]*reportEvent)
77		for _, rb := range bills {
78			for _, ev := range rb.events {
79				re := bySeq[ev.seq]
80				if re == nil {
81					re = &reportEvent{
82						seq: ev.seq, kind: ev.kind, refID: ev.refID, note: ev.note,
83						linkSeq: ev.linkSeq, payTotal: ev.payTotal, payID: ev.payID,
84					}
85					bySeq[ev.seq] = re
86				}
87				re.months = append(re.months, reportMonthDelta{
88					month:         rb.bill.Month,
89					deltaPayable:  ev.deltaPayable,
90					deltaReceived: ev.deltaReceived,
91					payAlloc:      ev.payAlloc,
92					beforeAlloc:   ev.beforeAlloc,
93					afterAlloc:    ev.afterAlloc,
94				})
95			}
96		}
97		out := make([]reportEvent, 0, len(bySeq))
98		for _, re := range bySeq {
99			if re.kind == "撤销收款" {
100				// 更正不得晚于撤销（载入时已校验），当前最新分配即撤销发生时的分配。
101				p := s.Payments[re.refID]
102				if !allocTouchesRange(currentAllocations(s, p), startMonth, endMonth) {
103					continue
104				}
105			}
106			// 金额无变化的月份不列入“范围内变化”（如更正只改动范围外月份、
107			// 或历史涉及但该月最新分配已为 0）。
108			kept := re.months[:0]
109			for _, md := range re.months {
110				if md.deltaPayable != 0 || md.deltaReceived != 0 {
111					kept = append(kept, md)
112				}
113			}
114			re.months = kept
115			sort.Slice(re.months, func(i, j int) bool { return re.months[i].month < re.months[j].month })
116			out = append(out, *re)
117		}
118		sort.Slice(out, func(i, j int) bool { return out[i].seq < out[j].seq })
119		return out
120	}
121	
122	// moneyFenBig 将任意精度“分”渲染为人民币金额，规则与 moneyFen 相同；
123	// 多账单汇总可能超出有符号 64 位上限，仍须精确输出。
124	func moneyFenBig(z *big.Int) string {
125		neg := z.Sign() < 0
126		s := z.String()
127		if neg {
128			s = s[1:]
129		}
130		if len(s) < 3 {
131			s = strings.Repeat("0", 3-len(s)) + s
132		}
133		out := s[:len(s)-2] + "." + s[len(s)-2:] + " 元"
134		if neg {
135			out = "-" + out
136		}
137		return out
138	}
139	
140	// reportBalance 是若干账单在同一序号截止后的汇总余额；合计可超出有符号
141	// 64 位上限，用任意精度整数精确累加。
142	type reportBalance struct {
143		payable  *big.Int
144		received *big.Int
145	}
146	
147	// sumBalanceAt 汇总全部选中账单在指定序号操作完成后的应付与实收。
148	func sumBalanceAt(bills []*reportBill, seq int64) reportBalance {
149		sum := reportBalance{payable: new(big.Int), received: new(big.Int)}
150		for _, rb := range bills {
151			p, r := balanceAtSeq(rb.bill, rb.events, seq)
152			sum.payable.Add(sum.payable, big.NewInt(p))
153			sum.received.Add(sum.received, big.NewInt(r))
154		}
155		return sum
156	}
157	
158	// outstanding 返回未收余额（应付 − 实收），不修改入参。
159	func (bal reportBalance) outstanding() *big.Int {
160		return new(big.Int).Sub(bal.payable, bal.received)
161	}
