163	func cmdBillReport(dir, customerID, startMonth, endMonth string, seqArgs []string) error {
164		if !validMonth(startMonth) {
165			return fmt.Errorf("起月 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", startMonth)
166		}
167		if !validMonth(endMonth) {
168			return fmt.Errorf("末月 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", endMonth)
169		}
170		if startMonth > endMonth {
171			return fmt.Errorf("起月 %s 晚于末月 %s，账期范围包含首尾且起月不得晚于末月", startMonth, endMonth)
172		}
173	
174		s, err := loadStore(dir)
175		if err != nil {
176			return err
177		}
178		cust, ok := s.Customers[customerID]
179		if !ok {
180			return fmt.Errorf("客户标识 %q 不存在", customerID)
181		}
182	
183		// 起止操作序号使用调整/收款/更正及其撤销共用的已保存全局序号：省略表示
184		// 0 至存档最新；须满足 0 ≤ 起点 ≤ 终点 ≤ 全局序号上限，空档合法。
185		startSeq, endSeq := int64(0), s.NextSeq
186		seqDesc := "省略，取 0 至存档最新"
187		if len(seqArgs) == 2 {
188			start, err := parseReportSeq(seqArgs[0], "起始操作序号")
189			if err != nil {
190				return err
191			}
192			end, err := parseReportSeq(seqArgs[1], "截止操作序号")
193			if err != nil {
194				return err
195			}
196			if start > end {
197				return fmt.Errorf("起始操作序号 %d 晚于截止操作序号 %d，须满足 0 ≤ 起点 ≤ 终点 ≤ 全局序号上限", start, end)
198			}
199			if end > s.NextSeq {
200				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", end, s.NextSeq)
201			}
202			startSeq, endSeq = start, end
203			seqDesc = "指定"
204		}
205	
206		// 只选择该客户账期范围内当前已存在的账单：不补结算、不按操作时间筛选。
207		var selected []*bill
208		for _, b := range s.Bills {
209			if b.CustomerID == customerID && b.Month >= startMonth && b.Month <= endMonth {
210				selected = append(selected, b)
211			}
212		}
213		sort.Slice(selected, func(i, j int) bool { return selected[i].Month < selected[j].Month })
214	
215		// 输出前核验所有选中账单的完整流水：任何异常（即使发生在终点序号之后）
216		// 都拒绝，不输出部分报表。
217		bills := make([]*reportBill, 0, len(selected))
