222			}
223			bills = append(bills, &reportBill{bill: b, events: events})
224		}
225	
226		events := mergeReportEvents(s, bills, startMonth, endMonth)
227		printBillReport(cust, s.NextSeq, startMonth, endMonth, startSeq, endSeq, seqDesc, bills, events)
228		return nil
229	}
