231	// parseReportSeq 解析报表的起止操作序号：非负有符号 64 位整数。
232	func parseReportSeq(text, name string) (int64, error) {
233		v, err := strconv.ParseInt(strings.TrimSpace(text), 10, 64)
234		if err != nil {
235			return 0, fmt.Errorf("%s %q 不是非负整数: %w", name, text, err)
236		}
237		if v < 0 {
